def migrate_ratings_to_turns(apps, schema_editor):
    EvaluationRating = apps.get_model("image_evaluator", "EvaluationRating")
    EvaluationTurn = apps.get_model("image_evaluator", "EvaluationTurn")
    EvaluationRun = apps.get_model("image_evaluator", "EvaluationRun")

    for rating in EvaluationRating.objects.all():
        EvaluationTurn.objects.create(
            run_id=rating.run_id,
            turn_index=rating.sample_index,
            sample_label=rating.sample_label,
            model=rating.model,
            status="success",
            response_text=rating.response,
            rating=rating.rating,
            notes=rating.notes,
            rated_at=rating.created_at,
            latency_wall_seconds=rating.latency_seconds,
            input_tokens=rating.input_tokens,
            output_tokens=rating.output_tokens,
            generated_at=rating.created_at,
        )

    for run in EvaluationRun.objects.all():
        last_rating = EvaluationRating.objects.filter(run_id=run.id).order_by("-created_at").first()
        if last_rating:
            run.status = "completed"
            run.completed_at = last_rating.created_at
            run.save(update_fields=["status", "completed_at"])


